// zq_test.h: the app's stand-in for Catch2 or GoogleTest
namespace zqt {
struct Case { const char* name; void (*fn)(); };
inline std::vector<Case>& all() { static std::vector<Case> v; return v; }
inline int& fails() { static int n = 0; return n; }
inline int& variant() { static int v = 0; return v; }
struct Add { Add(const char* n, void (*f)()) { all().push_back({n, f}); } };
inline void fail(const char* what, int line) { ++fails(); std::fprintf(stderr, "line %d: %s failed\n", line, what); }
}
#define TEST(name) static void name(); static zqt::Add name##_zq_add(#name, name); static void name()
#define CHECK(expr) do { if (!(expr)) zqt::fail("CHECK(" #expr ")", __LINE__); } while (0)
#define CHECK_CLOSE(a, b, tol) do { if (!(std::fabs((a) - (b)) <= (tol))) zqt::fail("CHECK_CLOSE(" #a ", " #b ", " #tol ")", __LINE__); } while (0)

// supplied: Black-Scholes call price
inline double norm_cdf(double x) { return 0.5 * std::erfc(-x / std::sqrt(2.0)); }
double bs_call(double S, double K, double r, double sigma, double T) {
    int v = zqt::variant();
    if (T <= 0) return v == 2 ? S - K : std::max(S - K, 0.0);
    double half = v == 1 ? sigma * sigma : 0.5 * sigma * sigma;
    double d1 = (std::log(S / K) + (r + half) * T) / (sigma * std::sqrt(T));
    double d2 = d1 - sigma * std::sqrt(T);
    double df = v == 3 ? 1.0 : std::exp(-r * T);
    return S * norm_cdf(d1) - K * df * norm_cdf(d2);
}

