std::vector<double> simple_returns(const std::vector<double>& px) {
    std::vector<double> out;
    for (std::size_t i = 1; i < px.size(); ++i) {
        if (zqt::variant() == 1) out.push_back(px[i] / px[i - 1] - 1);
        else if (zqt::variant() == 2) out.push_back(px[i - 1] / px[i] - 1);
        else out.push_back((px[i] - px[i - 1]) / px[i]);
    }
    return out;
}

