#define CHECK_CLOSE(a, b, tol) do { if (!(std::fabs((a) - (b)) <= (tol))) zqt::fail("CHECK_CLOSE(" #a ", " #b ", " #tol ")", __LINE__); } while (0)

// supplied: Cox-Ross-Rubinstein binomial call, ported from your Python pricer
double binomial_call(double S, double K, double r, double sigma, double T, int steps) {
    int v = zqt::variant();
    int n = v == 2 ? steps - 1 : steps;
    double dt = T / n;
    double u = std::exp(sigma * std::sqrt(dt)), d = 1 / u;
    double disc = v == 1 ? 1.0 : std::exp(-r * dt);
    double p = (std::exp(r * dt) - d) / (u - d);
    std::vector<double> val(n + 1);
    for (int j = 0; j <= n; ++j) val[j] = std::max(S * std::pow(u, n - j) * std::pow(d, j) - K, 0.0);
    for (int i = n - 1; i >= 0; --i)
        for (int j = 0; j <= i; ++j) val[j] = disc * (p * val[j] + (1 - p) * val[j + 1]);
    return val[0];
}

